import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const m=JSON.parse('{"title":"Members and roles","description":"","frontmatter":{},"headers":[],"relativePath":"guide/members.md","filePath":"guide/members.md"}'),s={name:"guide/members.md"};function r(o,e,l,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="members-and-roles" tabindex="-1">Members and roles <a class="header-anchor" href="#members-and-roles" aria-label="Permalink to &quot;Members and roles&quot;">​</a></h1><p>A workspace can have more people than the administrator who installed Orbit. Each person has a role in each workspace they belong to, and Orbit checks it on every request.</p><h2 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles {#roles}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Can</th></tr></thead><tbody><tr><td>Owner</td><td>Everything in the workspace, including its members and other owners</td></tr><tr><td>Admin</td><td>Everything except managing owners: creating and deleting projects, environments and databases, domains, integrations, notification channels, backup storages, restores, credentials and members</td></tr><tr><td>Developer</td><td>Deploy, roll back, change build settings, variables and resources, run jobs, back up, browse a database&#39;s data, open a <a href="./applications#terminal">terminal</a> in an application&#39;s instances and read repositories from the connected Git providers</td></tr><tr><td>Viewer</td><td>See everything except secret values, credentials and a database&#39;s data</td></tr></tbody></table><ul><li><strong>What stays with admins and owners:</strong> restoring a backup, deleting anything, revealing or rotating a database&#39;s credentials, opening a <a href="./databases#shell">database shell</a>, upgrading or migrating a database, failing over and importing data.</li><li><strong>Orbit&#39;s administrator</strong> is the person who installed Orbit. Servers, Orbit updates and new workspaces stay with them, and they own every workspace. This is separate from the workspace roles, and Orbit has one administrator for now.</li><li><strong>In the console</strong>, what your role cannot do is disabled and says which role it needs. The workspace switcher shows your role.</li></ul><h2 id="inviting" tabindex="-1">Inviting someone <a class="header-anchor" href="#inviting" aria-label="Permalink to &quot;Inviting someone {#inviting}&quot;">​</a></h2><ol><li>In <strong>Settings → Members</strong>, type the email and pick the role. Admins invite admins, developers and viewers; only owners invite owners.</li><li>When <a href="./notifications#email-setup">email is set up</a>, Orbit emails the link to that person. Otherwise, or if the email server refuses it, send the link the way you usually talk to them. Either way the link is shown once, works once, for seven days, and Orbit keeps only a hash of it.</li><li>The person opens the link, creates an account with a name and a password of at least 12 characters, and lands in the workspace. Someone who already has an account in this Orbit signs in with it instead and gets the new workspace beside the ones they had. With <a href="./sign-in#invitations">GitHub or Google sign-in</a> set up, the person can also join with a provider that has verified the invited email.</li></ol><ul><li><strong>Pending invitations</strong> are listed below the members and can be revoked. Inviting the same address again replaces the earlier link.</li><li><strong>Failed attempts</strong> at accepting are rate limited like signing in.</li></ul><h2 id="removing" tabindex="-1">Changing roles and removing <a class="header-anchor" href="#removing" aria-label="Permalink to &quot;Changing roles and removing {#removing}&quot;">​</a></h2><ul><li><strong>Roles</strong> change from the member&#39;s row. Admins change developers and viewers; owners change anyone.</li><li><strong>The last owner</strong> keeps the role and cannot leave, so a workspace always has someone who can manage it.</li><li><strong>Removing someone signs them out everywhere at once</strong>, and their open console stops receiving updates. Their account stays, so they can be invited back.</li><li><strong>Leaving:</strong> anyone can leave a workspace from their own row and stays signed in for the other workspaces they belong to.</li></ul><h2 id="visibility" tabindex="-1">What each person sees <a class="header-anchor" href="#visibility" aria-label="Permalink to &quot;What each person sees {#visibility}&quot;">​</a></h2><ul><li>Lists, the activity and the live updates only carry the workspaces a person belongs to. A link to a project in another workspace answers as if it did not exist.</li><li>Servers are shared, so everyone sees them, but only the administrator changes them.</li><li>Scripts and CI use <a href="./api-tokens">API tokens</a>, which act with a role of their own instead of a person&#39;s account.</li><li>The API checks the role on every operation. The contract names the role each operation needs in <code>x-orbit-role</code>, and a role that is too low gets <code>403 roleRequired</code> with the role it needs.</li></ul>',12)])])}const p=a(s,[["render",r]]);export{m as __pageData,p as default};
